const main=document.querySelector('#main');
const nav=document.querySelector('#bottomNav');
const badge=document.querySelector('#syncBadge');
const toast=document.querySelector('#toast');
let unlocked=false,route='home',lockTimer=null;
let editingTransactionId=null;
let txFilters={q:'',type:'all',category:'all',from:'',to:''};
const PROFILE_ID='owner',SETTINGS_ID='main',DIAGNOSIS_ID='current';
const currencyOptions=['USD','EUR','VES','COP','MXN','ARS','BRL'];
const workFields=[
  ['transport','Transporte al trabajo'],['lunch','Comida durante el trabajo'],['phone','Celular / internet de trabajo'],
  ['tools','Herramientas / ropa de trabajo'],['workOther','Otros costos de trabajar']
];
const commitmentFields=[
  ['housing','Alquiler o cuota de vivienda'],['utilities','Servicios básicos'],['debtPayments','Cuotas de deudas'],
  ['healthInsurance','Salud y seguros'],['education','Colegio / educación'],['commitmentOther','Otros compromisos fijos']
];

const expenseCategories=['Vivienda','Comida en casa','Comida fuera de casa','Transporte','Salud','Obligaciones','Personal','Suscripciones / servicios digitales','Ahorro / metas','Otros'];
const incomeCategories=['Ingreso principal','Ingreso extra','Venta / reintegro','Otros ingresos'];
const paymentMethods=['Efectivo','Débito','Crédito','Transferencia','Pago móvil','Otro'];
function localDateISO(){const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)}
function monthKey(v){const d=new Date(`${v}T12:00:00`);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function inLastDays(date,days){const d=new Date(`${date}T12:00:00`);const now=new Date();const start=new Date(now.getFullYear(),now.getMonth(),now.getDate()-days+1);return d>=start&&d<=new Date(now.getFullYear(),now.getMonth(),now.getDate(),23,59,59)}

function showToast(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2800)}
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]))}
function num(v){const x=Number(String(v??'').replace(',','.'));return Number.isFinite(x)&&x>=0?x:0}
function sum(obj,fields){return fields.reduce((a,[k])=>a+num(obj?.[k]),0)}
function fmt(v,c='USD'){try{return new Intl.NumberFormat('es-VE',{style:'currency',currency:c,maximumFractionDigits:2}).format(Number(v||0))}catch{return `${Number(v||0).toFixed(2)} ${c}`}}
function pct(v){return `${Math.round(Number(v||0)*100)}%`}
function dateLabel(v){try{return new Intl.DateTimeFormat('es-VE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))}catch{return v||'—'}}
function signedMoney(v,c){const n=Number(v||0);return `${n>0?'+':''}${fmt(n,c)}`}
function stableKey(text=''){let h=5381;for(const ch of String(text)){h=((h<<5)+h)^ch.charCodeAt(0)}return (h>>>0).toString(36)}
function leakReviewId(kind,label){return `leak_${stableKey(`${String(kind).toLowerCase()}|${String(label).trim().toLowerCase()}`)}`}
function leakStatusLabel(v){return v==='necessary'?'Necesario':v==='later'?'Revisar después':v==='correctable'?'Corregible':'Sin revisar'}

function downloadBlob(text,name,type='application/octet-stream'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function updateStatus(){const q=await queueSize();if(!navigator.onLine){badge.textContent='Sin conexión · seguro en el dispositivo';badge.className='sync-badge warn';return}badge.textContent=q?`En línea · ${q} cambio${q===1?'':'s'} local${q===1?'':'es'}`:'En línea · datos locales';badge.className='sync-badge ok'}
async function settings(){return await get('settings',SETTINGS_ID)||{id:SETTINGS_ID,currency:'USD',autoLockMinutes:5}}
function resetLockTimer(){if(!unlocked)return;clearTimeout(lockTimer);settings().then(s=>{const m=Number(s.autoLockMinutes||0);if(m>0)lockTimer=setTimeout(async()=>{unlocked=false;route='home';await render();showToast('Mi Dinero se bloqueó por inactividad')},m*60000)})}
function calcDiagnosis(d){
  const monthly=(d?.variableMonths||[]).map(num).filter(v=>v>0);
  const threeWorst=[...monthly].sort((a,b)=>a-b).slice(0,3);
  const gross=d?.incomeType==='variable'?(threeWorst.length>=3?threeWorst.reduce((a,b)=>a+b,0)/3:0):num(d?.grossMonthly);
  const taxes=num(d?.taxes);
  const net=Math.max(0,gross-taxes);
  const work=sum(d,workFields);
  const adjusted=Math.max(0,net-work);
  const commitments=sum(d,commitmentFields);
  const available=adjusted-commitments;
  return {gross,taxes,net,work,adjusted,commitments,available,monthly,threeWorst};
}
function inputMoney(name,label,value=''){return `<label>${label}</label><input name="${name}" inputmode="decimal" min="0" step="0.01" value="${value??''}" placeholder="0.00">`}

async function bootstrap(){
  if('serviceWorker' in navigator){try{await navigator.serviceWorker.register('./sw.js')}catch(e){console.warn(e)}}
  window.addEventListener('online',()=>{updateStatus();showToast('Internet disponible')});window.addEventListener('offline',()=>{updateStatus();showToast('Sigues trabajando sin internet')});
  ['click','keydown','touchstart'].forEach(ev=>document.addEventListener(ev,resetLockTimer,{passive:true}));
  document.addEventListener('click',onClick);document.addEventListener('submit',onSubmit);document.addEventListener('change',onChange);
  await render();await updateStatus();
}
async function setupView(){return `<section class="card hero"><div class="eyebrow">Configuración inicial</div><h2>Tu sistema financiero personal.</h2><p class="muted">Funciona sin internet y tus datos se guardan primero en este dispositivo.</p></section><section class="card"><form id="setupForm"><label>Tu nombre</label><input name="name" required maxlength="50" placeholder="Tu nombre"><label>Moneda principal</label><select name="currency">${currencyOptions.map(c=>`<option>${c}</option>`).join('')}</select><label>PIN de acceso</label><input name="pin" type="password" inputmode="numeric" pattern="[0-9]{4,8}" required placeholder="4 a 8 números"><label>Repite el PIN</label><input name="pin2" type="password" inputmode="numeric" pattern="[0-9]{4,8}" required><button class="btn" type="submit">Preparar Mi Dinero</button></form></section>`}
async function lockView(p){const s=await settings();const lockedUntil=Number(s.lockedUntil||0);const wait=Math.max(0,Math.ceil((lockedUntil-Date.now())/1000));return `<section class="lock-wrap"><section class="card lock-card"><div class="app-mark">$</div><div class="eyebrow">Mi Dinero</div><h2>Hola, ${esc(p.name)}</h2><p class="muted">${wait?`Demasiados intentos. Espera ${wait} segundos.`:'Introduce tu PIN. No necesitas internet.'}</p><form id="unlockForm"><input class="pin-input" name="pin" type="password" inputmode="numeric" pattern="[0-9]{4,8}" required ${wait?'disabled':''} autofocus placeholder="••••"><button class="btn" type="submit" ${wait?'disabled':''}>Entrar</button></form><div class="small muted center">Tus datos permanecen en este dispositivo.</div></section></section>`}

async function homeView(){
  const p=await get('profile',PROFILE_ID),s=await settings(),d=await get('diagnosis',DIAGNOSIS_ID),snaps=await all('backups');
  const c=d?calcDiagnosis(d):null;
  return `<section class="card hero"><div class="eyebrow">Hola, ${esc(p.name)}</div><h2>${d?.completed?'Tu disponible real':'Vamos a medir tu dinero de verdad'}</h2>${d?.completed?`<div class="money-hero ${c.available<0?'negative':''}">${fmt(c.available,s.currency)}</div><p class="muted">Es lo que queda después de impuestos, costos de trabajar y compromisos que ya tienen dueño.</p><div class="row wrap"><span class="pill">Bruto · ${fmt(c.gross,s.currency)}</span><span class="pill">Neto · ${fmt(c.net,s.currency)}</span><span class="pill">Ajustado · ${fmt(c.adjusted,s.currency)}</span></div>`:`<p class="muted">La Parte 2 ya está activa. Completa tu diagnóstico para calcular bruto, neto, neto ajustado y disponible real.</p><button class="btn" data-route="diagnosis">Comenzar diagnóstico</button>`}</section>
  ${d?.completed?`<section class="grid two"><div class="stat"><div class="muted small">Compromisos fijos</div><div class="value">${fmt(c.commitments,s.currency)}</div><div class="small muted">${c.adjusted>0?pct(c.commitments/c.adjusted):'—'} del neto ajustado</div></div><div class="stat"><div class="muted small">Costos de trabajar</div><div class="value">${fmt(c.work,s.currency)}</div><div class="small muted">Antes de gastos personales</div></div></section><section class="card"><h3>Lectura rápida</h3>${c.available>0?`<p class="muted">Tus decisiones de presupuesto y ahorro se calcularán sobre <strong>${fmt(c.available,s.currency)}</strong>, no sobre el ingreso bruto.</p>`:`<div class="alert danger-soft">Tus compromisos superan el neto ajustado en <strong>${fmt(Math.abs(c.available),s.currency)}</strong>. Antes de presupuestar, conviene identificar qué renglones pueden cambiar.</div>`}<button class="btn secondary" data-route="diagnosis">Revisar diagnóstico</button></section>`:''}
  <section class="card"><h3>Estado del sistema</h3><div class="stack small"><div>✓ Uso personal</div><div>✓ Funciona sin internet</div><div>✓ Acceso por PIN</div><div>✓ Respaldo cifrado</div><div>✓ ${snaps.length} snapshot${snaps.length===1?'':'s'} local${snaps.length===1?'':'es'}</div><div>${d?.completed?'✓':'○'} Diagnóstico financiero</div></div></section>`
}

async function diagnosisView(){
  const d=await get('diagnosis',DIAGNOSIS_ID)||{id:DIAGNOSIS_ID,incomeType:'fixed',variableMonths:Array(12).fill('')};
  const s=await settings(),c=calcDiagnosis(d),complete=!!d.completed;
  const history=(await all('diagnosisHistory')).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
  const prev=history[1]||null; const delta=prev?c.available-Number(prev.calculated?.available||0):null;
  const months=Array.from({length:12},(_,i)=>`<div><label>Mes ${i+1}${i===0?' · más reciente':''}</label><input name="month_${i}" inputmode="decimal" min="0" step="0.01" value="${d.variableMonths?.[i]??''}" placeholder="0.00"></div>`).join('');
  return `<section class="card hero"><div class="eyebrow">Parte 2 · Diagnóstico financiero</div><h2>¿Cuánto dinero tienes realmente disponible?</h2><p class="muted">Vamos a separar ingreso bruto, impuestos, costos de trabajar y compromisos fijos. Este cálculo será la base del resto de la app.</p></section>
  ${complete?`<section class="card result-card"><div class="eyebrow">Resultado actual</div><div class="four-levels"><div><span>1 · Bruto</span><strong>${fmt(c.gross,s.currency)}</strong></div><div><span>2 · Neto</span><strong>${fmt(c.net,s.currency)}</strong></div><div><span>3 · Neto ajustado</span><strong>${fmt(c.adjusted,s.currency)}</strong></div><div class="featured"><span>4 · Disponible real</span><strong>${fmt(c.available,s.currency)}</strong></div></div>${d.incomeType==='variable'?`<p class="small muted">Base prudente usada: promedio de los 3 meses más bajos registrados (${c.threeWorst.map(v=>fmt(v,s.currency)).join(' · ')}).</p>`:''}</section>`:''}
  ${complete?`<section class="card"><div class="row between"><div><div class="eyebrow">Evolución</div><h3>Comparación del diagnóstico</h3></div><span class="pill">${history.length} registro${history.length===1?'':'s'}</span></div>${prev?`<div class="grid two"><div class="stat"><div class="muted small">Cambio del disponible real</div><div class="value ${delta<0?'negative':''}">${signedMoney(delta,s.currency)}</div><div class="small muted">vs. diagnóstico anterior</div></div><div class="stat"><div class="muted small">Anterior</div><div class="value">${fmt(prev.calculated?.available,s.currency)}</div><div class="small muted">${dateLabel(prev.createdAt)}</div></div></div>`:`<p class="muted">Este es tu primer diagnóstico. Cuando lo actualices, aquí verás si tu disponible real mejoró o empeoró.</p>`}</section><section class="card"><h3>Historial</h3><div class="stack">${history.slice(0,6).map((h,i)=>`<div class="history-row"><div><strong>${i===0?'Actualización más reciente':'Diagnóstico anterior'}</strong><div class="small muted">${dateLabel(h.createdAt)} · ${h.incomeType==='variable'?'Ingreso variable':'Ingreso fijo'}</div></div><div class="right"><strong>${fmt(h.calculated?.available,s.currency)}</strong><div class="small muted">disponible real</div></div></div>`).join('')||'<div class="muted">Aún no hay historial.</div>'}</div></section>`:''}
  <form id="diagnosisForm">
    <section class="card"><div class="section-number">1</div><h3>Tipo de ingreso</h3><label>¿Cómo recibes tus ingresos?</label><select id="incomeType" name="incomeType"><option value="fixed" ${d.incomeType==='fixed'?'selected':''}>Ingreso fijo</option><option value="variable" ${d.incomeType==='variable'?'selected':''}>Ingreso variable</option></select><div id="fixedIncomeBox" class="${d.incomeType==='variable'?'hidden':''}">${inputMoney('grossMonthly','Ingreso bruto mensual',d.grossMonthly??'')}</div><div id="variableIncomeBox" class="${d.incomeType==='variable'?'':'hidden'}"><p class="muted small">Registra hasta 12 meses. La app tomará los 3 más bajos y usará su promedio como base prudente. Se necesitan al menos 3 meses.</p><div class="month-grid">${months}</div></div></section>
    <section class="card"><div class="section-number">2</div><h3>Impuestos y retenciones</h3><p class="muted small">Dinero que no llega realmente a estar disponible para gastar.</p>${inputMoney('taxes','Aportes, retenciones e impuestos mensuales',d.taxes??'')}</section>
    <section class="card"><div class="section-number">3</div><h3>Costos de trabajar</h3><p class="muted small">Gastos que existen porque trabajas.</p>${workFields.map(([k,l])=>inputMoney(k,l,d[k]??'')).join('')}</section>
    <section class="card"><div class="section-number">4</div><h3>Compromisos que ya tienen dueño</h3><p class="muted small">Obligaciones que debes cubrir antes de decidir qué hacer con el resto.</p>${commitmentFields.map(([k,l])=>inputMoney(k,l,d[k]??'')).join('')}</section>
    <section class="card sticky-save"><button class="btn" type="submit">Calcular y guardar diagnóstico</button><p class="small muted center">Se guarda en este dispositivo y funciona sin internet.</p></section>
  </form>`
}


async function transactionsView(){
  const s=await settings();
  const diagnosis=await get('diagnosis',DIAGNOSIS_ID);
  const diag=diagnosis?.completed?calcDiagnosis(diagnosis):null;
  const allItems=(await all('transactions')).filter(x=>!x.deletedAt).sort((a,b)=>`${b.date||''}${b.createdAt||''}`.localeCompare(`${a.date||''}${a.createdAt||''}`));
  const recurring=(await all('recurringTransactions')).filter(x=>!x.deletedAt).sort((a,b)=>String(a.note).localeCompare(String(b.note)));
  const editItem=editingTransactionId?allItems.find(x=>x.id===editingTransactionId):null;
  const today=localDateISO(),currentMonth=monthKey(today),monthItems=allItems.filter(x=>monthKey(x.date)===currentMonth);
  const monthIncome=monthItems.filter(x=>x.type==='income').reduce((a,x)=>a+num(x.amount),0);
  const monthExpense=monthItems.filter(x=>x.type==='expense').reduce((a,x)=>a+num(x.amount),0);
  const now=new Date();
  const daysElapsed=Math.max(1,now.getDate());
  const daysInMonth=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();
  const daysLeft=Math.max(0,daysInMonth-daysElapsed);
  const avgDaily=monthExpense/daysElapsed;
  const projectedExpense=avgDaily*daysInMonth;
  const available=diag?.available??null;
  const remainingAvailable=available===null?null:available-monthExpense;
  const dailyRoom=remainingAvailable===null?null:(daysLeft>0?remainingAvailable/daysLeft:remainingAvailable);
  const paceRatio=available>0?monthExpense/available:null;
  const projectedBalance=available===null?null:available-projectedExpense;
  const last30=allItems.filter(x=>x.type==='expense'&&inLastDays(x.date,30));
  const total30=last30.reduce((a,x)=>a+num(x.amount),0);
  const byCat={};for(const x of last30)byCat[x.category]=(byCat[x.category]||0)+num(x.amount);
  const cats=Object.entries(byCat).sort((a,b)=>b[1]-a[1]);
  const biggest=cats[0];
  const repeatMap={};
  for(const x of last30){const key=`${String(x.note||'').trim().toLowerCase()}|${x.category}`;if(!key.startsWith('|')){repeatMap[key]=repeatMap[key]||{note:x.note,category:x.category,count:0,total:0,amounts:[]};repeatMap[key].count++;repeatMap[key].total+=num(x.amount);repeatMap[key].amounts.push(num(x.amount));}}
  const repeated=Object.values(repeatMap).filter(x=>x.count>=2).sort((a,b)=>b.total-a.total).slice(0,5);
  const nonHousing=cats.filter(([cat])=>cat!=='Vivienda');
  const biggestNonHousing=nonHousing[0]||null;
  const thirtyDayIncome=allItems.filter(x=>x.type==='income'&&inLastDays(x.date,30)).reduce((a,x)=>a+num(x.amount),0);
  const thirtyDayNet=thirtyDayIncome-total30;
  const hole=available===null?null:available-total30;
  const categoryShareAvailable=available>0?cats.map(([cat,val])=>[cat,val,val/available]):cats.map(([cat,val])=>[cat,val,null]);
  const q=txFilters.q.toLowerCase().trim();
  const filtered=allItems.filter(x=>{
    if(txFilters.type!=='all'&&x.type!==txFilters.type)return false;
    if(txFilters.category!=='all'&&x.category!==txFilters.category)return false;
    if(txFilters.from&&x.date<txFilters.from)return false;
    if(txFilters.to&&x.date>txFilters.to)return false;
    if(q&&!`${x.note} ${x.category} ${x.paymentMethod}`.toLowerCase().includes(q))return false;
    return true;
  });
  const formType=editItem?.type||'expense';
  const formCats=formType==='income'?incomeCategories:expenseCategories;
  const paceMessage=available===null
    ?`Completa tu diagnóstico para comparar tus gastos con tu disponible real.`
    :projectedBalance>=0
      ?`A este ritmo terminarías el mes con aproximadamente <strong>${fmt(projectedBalance,s.currency)}</strong> de tu disponible real.`
      :`A este ritmo podrías superar tu disponible real en aproximadamente <strong>${fmt(Math.abs(projectedBalance),s.currency)}</strong>.`;
  return `<section class="card hero"><div class="eyebrow">Parte 3 · Movimientos</div><h2>Registra en segundos.</h2><p class="muted">Cada movimiento se guarda primero en este dispositivo. Puedes hacerlo sin internet.</p><div class="grid two compact-stats"><div class="stat"><div class="muted small">Ingresos del mes</div><strong>${fmt(monthIncome,s.currency)}</strong></div><div class="stat"><div class="muted small">Gastos del mes</div><strong>${fmt(monthExpense,s.currency)}</strong></div></div></section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Ritmo del mes</div><h3>¿Cómo vas hoy?</h3></div><span class="pill">Día ${daysElapsed} de ${daysInMonth}</span></div><div class="grid two"><div class="stat"><div class="muted small">Promedio diario</div><div class="value">${fmt(avgDaily,s.currency)}</div><div class="small muted">según lo registrado este mes</div></div><div class="stat"><div class="muted small">Proyección de gasto</div><div class="value ${projectedBalance!==null&&projectedBalance<0?'negative':''}">${fmt(projectedExpense,s.currency)}</div><div class="small muted">si mantienes el mismo ritmo</div></div></div>${available===null?`<div class="insight">${paceMessage} <button class="link-btn" data-route="diagnosis">Ir al diagnóstico</button></div>`:`<div class="grid two"><div class="stat"><div class="muted small">Disponible real del mes</div><div class="value">${fmt(available,s.currency)}</div><div class="small muted">base para tus decisiones</div></div><div class="stat"><div class="muted small">Te queda por gastar</div><div class="value ${remainingAvailable<0?'negative':''}">${fmt(remainingAvailable,s.currency)}</div><div class="small muted">${daysLeft} día${daysLeft===1?'':'s'} por delante</div></div></div><div class="progress-line"><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,Math.max(0,(paceRatio||0)*100))}%"></div></div><div class="row between tiny muted"><span>${paceRatio===null?'—':Math.round(paceRatio*100)+'%'} del disponible usado</span><span>${dailyRoom===null?'':`Margen diario: ${fmt(dailyRoom,s.currency)}`}</span></div></div><div class="insight ${projectedBalance<0?'warning-insight':''}">${paceMessage}</div>`}</section>
  <section class="card"><div class="row between"><h3>${editItem?'Editar movimiento':'Nuevo movimiento'}</h3>${editItem?'<button class="btn secondary small-btn" data-action="cancel-edit">Cancelar</button>':''}</div><form id="transactionForm"><input type="hidden" name="id" value="${esc(editItem?.id||'')}"><div class="segmented"><label><input type="radio" name="type" value="expense" ${formType==='expense'?'checked':''}><span>Gasto</span></label><label><input type="radio" name="type" value="income" ${formType==='income'?'checked':''}><span>Ingreso</span></label></div><div class="amount-row"><span class="currency-prefix">${esc(s.currency)}</span><input class="amount-input" name="amount" inputmode="decimal" min="0.01" step="0.01" required value="${editItem?.amount??''}" placeholder="0.00"></div><label>¿Qué fue?</label><input name="note" maxlength="80" required value="${esc(editItem?.note||'')}" placeholder="Ej. Supermercado"><label>Categoría</label><select name="category" id="transactionCategory">${formCats.map(c=>`<option ${c===editItem?.category?'selected':''}>${c}</option>`).join('')}</select><div class="grid two"><div><label>Fecha</label><input name="date" type="date" value="${editItem?.date||today}" required></div><div><label>Medio de pago</label><select name="paymentMethod">${paymentMethods.map(c=>`<option ${c===editItem?.paymentMethod?'selected':''}>${c}</option>`).join('')}</select></div></div>${!editItem?`<label class="check-row"><input type="checkbox" name="makeRecurring" id="makeRecurring"> Guardar también como recurrente</label><div id="recurringOptions" class="hidden"><label>Frecuencia</label><select name="frequency"><option value="monthly">Mensual</option><option value="weekly">Semanal</option><option value="biweekly">Quincenal</option><option value="yearly">Anual</option></select></div>`:''}<button class="btn" type="submit">${editItem?'Guardar cambios':'Guardar movimiento'}</button></form></section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Mapa de 30 días</div><h3>¿Adónde se está yendo?</h3></div><strong>${fmt(total30,s.currency)}</strong></div>${cats.length?`<div class="category-bars">${cats.map(([cat,val])=>`<div class="bar-row"><div class="row between small"><span>${esc(cat)}</span><strong>${fmt(val,s.currency)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(4,total30?val/total30*100:0)}%"></div></div><div class="muted tiny">${total30?Math.round(val/total30*100):0}% de tus gastos de 30 días</div></div>`).join('')}</div>${biggest?`<div class="insight">Tu categoría más alta en los últimos 30 días es <strong>${esc(biggest[0])}</strong> con ${fmt(biggest[1],s.currency)}.</div>`:''}`:'<p class="muted">Todavía no hay gastos suficientes para construir tu mapa.</p>'}</section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Cierre de 30 días</div><h3>Lectura para decidir</h3></div><span class="pill">${last30.length} gasto${last30.length===1?'':'s'}</span></div><div class="grid two"><div class="stat"><div class="muted small">Ingresos registrados</div><div class="value">${fmt(thirtyDayIncome,s.currency)}</div><div class="small muted">últimos 30 días</div></div><div class="stat"><div class="muted small">Balance registrado</div><div class="value ${thirtyDayNet<0?'negative':''}">${fmt(thirtyDayNet,s.currency)}</div><div class="small muted">ingresos menos gastos registrados</div></div></div>${available!==null?`<div class="stat close-stat"><div class="row between"><div><div class="muted small">Contra tu disponible real</div><div class="value ${hole<0?'negative':''}">${fmt(hole,s.currency)}</div></div><span class="pill">${available>0?Math.round(total30/available*100)+'% usado':'sin margen'}</span></div><div class="small muted">${hole>=0?'Aún queda margen dentro de tu disponible real.':'Tus gastos registrados superan el disponible real de referencia.'}</div></div>`:'<div class="insight">Completa el diagnóstico para comparar este cierre con tu disponible real.</div>'}${biggestNonHousing?`<div class="insight">Fuera de vivienda, tu categoría más grande es <strong>${esc(biggestNonHousing[0])}</strong> con ${fmt(biggestNonHousing[1],s.currency)}. Esta será una de las primeras que revisará el Detector de Fugas.</div>`:''}${categoryShareAvailable.length&&available>0?`<details class="details-box"><summary>Ver peso de cada categoría sobre mi disponible real</summary><div class="stack category-share">${categoryShareAvailable.map(([cat,val,share])=>`<div class="row between small"><span>${esc(cat)}</span><strong>${Math.round(share*100)}% · ${fmt(val,s.currency)}</strong></div>`).join('')}</div></details>`:''}</section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Detección inicial</div><h3>Gastos que se repiten</h3></div><span class="pill">${repeated.length}</span></div>${repeated.length?`<div class="stack">${repeated.map(r=>`<div class="history-row"><div><strong>${esc(r.note)}</strong><div class="small muted">${esc(r.category)} · ${r.count} veces en 30 días</div></div><div class="right"><strong>${fmt(r.total,s.currency)}</strong><div class="small muted">total acumulado</div></div></div>`).join('')}</div><p class="muted small">Esto todavía no marca un gasto como “malo”. Solo identifica patrones repetidos para revisarlos después en el Detector de Fugas.</p>`:'<p class="muted">Aún no detecto descripciones repetidas suficientes en los últimos 30 días.</p>'}</section>
  <section class="card"><div class="row between"><h3>Recurrentes</h3><span class="pill">${recurring.length}</span></div>${recurring.length?`<div class="transaction-list">${recurring.map(r=>`<div class="transaction-item"><div class="transaction-icon ${r.type}">↻</div><div class="transaction-main"><strong>${esc(r.note)}</strong><div class="muted tiny">${esc(r.category)} · ${frequencyLabel(r.frequency)} · ${fmt(r.amount,s.currency)}</div></div><button class="btn secondary mini" data-action="run-recurring" data-id="${esc(r.id)}">Registrar hoy</button><button class="icon-btn" data-action="delete-recurring" data-id="${esc(r.id)}" title="Eliminar">×</button></div>`).join('')}</div>`:'<p class="muted">Aún no tienes movimientos recurrentes.</p>'}</section>
  <section class="card"><div class="row between"><h3>Historial</h3><span class="pill">${filtered.length} de ${allItems.length}</span></div><form id="transactionFilterForm" class="filters"><input name="q" value="${esc(txFilters.q)}" placeholder="Buscar"><div class="grid two"><select name="type"><option value="all" ${txFilters.type==='all'?'selected':''}>Todos</option><option value="expense" ${txFilters.type==='expense'?'selected':''}>Gastos</option><option value="income" ${txFilters.type==='income'?'selected':''}>Ingresos</option></select><select name="category"><option value="all">Todas las categorías</option>${[...expenseCategories,...incomeCategories].filter((v,i,a)=>a.indexOf(v)===i).map(c=>`<option ${txFilters.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="grid two"><div><label>Desde</label><input type="date" name="from" value="${txFilters.from}"></div><div><label>Hasta</label><input type="date" name="to" value="${txFilters.to}"></div></div><div class="row"><button class="btn secondary" type="submit">Aplicar filtros</button><button class="btn ghost" type="button" data-action="clear-filters">Limpiar</button></div></form>${filtered.length?`<div class="transaction-list">${filtered.map(x=>`<div class="transaction-item"><div class="transaction-icon ${x.type}">${x.type==='income'?'↑':'↓'}</div><div class="transaction-main"><strong>${esc(x.note)}</strong><div class="muted tiny">${esc(x.category)} · ${esc(x.paymentMethod)} · ${esc(x.date)}${x.linkedContributionId?' · aporte vinculado':''}${x.linkedDebtPaymentId?' · pago de deuda vinculado':''}</div></div><div class="transaction-amount ${x.type}">${x.type==='income'?'+':'-'}${fmt(x.amount,s.currency)}</div><button class="icon-btn" data-action="edit-transaction" data-id="${esc(x.id)}" title="Editar">✎</button><button class="icon-btn" data-action="delete-transaction" data-id="${esc(x.id)}" title="Eliminar">×</button></div>`).join('')}</div>`:'<p class="muted">No hay movimientos que coincidan con los filtros.</p>'}</section>`
}

function frequencyLabel(v){return ({monthly:'Mensual',weekly:'Semanal',biweekly:'Quincenal',yearly:'Anual'})[v]||v||'Recurrente'}


async function budgetView(){
  const s=await settings(), diagnosis=await get('diagnosis',DIAGNOSIS_ID), diag=diagnosis?.completed?calcDiagnosis(diagnosis):null;
  const items=(await all('transactions')).filter(x=>!x.deletedAt&&x.type==='expense');
  const today=localDateISO(), currentMonth=monthKey(today);
  const nowDate=new Date(`${today}T12:00:00`), prevDate=new Date(nowDate.getFullYear(),nowDate.getMonth()-1,1);
  const prevMonth=`${prevDate.getFullYear()}-${String(prevDate.getMonth()+1).padStart(2,'0')}`;
  const monthItems=items.filter(x=>monthKey(x.date)===currentMonth), prevItems=items.filter(x=>monthKey(x.date)===prevMonth);
  const spent={},prevSpent={};for(const x of monthItems)spent[x.category]=(spent[x.category]||0)+num(x.amount);for(const x of prevItems)prevSpent[x.category]=(prevSpent[x.category]||0)+num(x.amount);
  const saved=await get('budgets',currentMonth); const base=diag?.available>0?diag.available:0;
  const defaults={'Vivienda':base*.30,'Comida en casa':base*.18,'Comida fuera de casa':base*.07,'Transporte':base*.15,'Salud':base*.07,'Obligaciones':base*.08,'Personal':base*.07,'Suscripciones / servicios digitales':base*.03,'Otros':base*.05};
  const limits={...defaults,...(saved?.limits||{})};
  const totalLimit=expenseCategories.reduce((a,c)=>a+num(limits[c]),0), totalSpent=expenseCategories.reduce((a,c)=>a+num(spent[c]),0), remaining=totalLimit-totalSpent;
  const rows=expenseCategories.map(c=>{const lim=num(limits[c]),used=num(spent[c]),ratio=lim>0?used/lim:used>0?2:0;return {c,lim,used,ratio,left:lim-used}});
  const alerts=rows.filter(r=>r.ratio>=.8).sort((a,b)=>b.ratio-a.ratio);
  const last30=items.filter(x=>inLastDays(x.date,30));
  const repeat={};for(const x of last30){const k=`${String(x.note||'').trim().toLowerCase()}|${x.category}`;if(!k.startsWith('|')){repeat[k]=repeat[k]||{note:x.note,category:x.category,count:0,total:0};repeat[k].count++;repeat[k].total+=num(x.amount)}}
  const repeats=Object.values(repeat).filter(x=>x.count>=2).sort((a,b)=>b.total-a.total);
  const digital=last30.filter(x=>x.category==='Suscripciones / servicios digitales').reduce((a,x)=>a+num(x.amount),0);
  const outside=last30.filter(x=>x.category==='Comida fuera de casa').reduce((a,x)=>a+num(x.amount),0);
  const increases=expenseCategories.map(c=>{const cur=num(spent[c]),prev=num(prevSpent[c]);return {c,cur,prev,delta:cur-prev,p:prev>0?(cur-prev)/prev:null}}).filter(x=>x.prev>0&&x.delta>0&&x.p>=.20).sort((a,b)=>b.delta-a.delta);
  const microThreshold=base>0?Math.max(2,base*.015):10; const micros=last30.filter(x=>num(x.amount)>0&&num(x.amount)<=microThreshold); const microTotal=micros.reduce((a,x)=>a+num(x.amount),0);
  const dupMap={};for(const x of last30){const k=`${x.date}|${String(x.note||'').trim().toLowerCase()}|${num(x.amount).toFixed(2)}`;(dupMap[k]??=[]).push(x)}
  const duplicates=Object.values(dupMap).filter(g=>g.length>=2).map(g=>({note:g[0].note,date:g[0].date,amount:num(g[0].amount),count:g.length,possibleExtra:num(g[0].amount)*(g.length-1)})).sort((a,b)=>b.possibleExtra-a.possibleExtra);
  const candidates=[];
  if(digital>0)candidates.push({kind:'Suscripción',label:'Suscripciones y servicios digitales',amount:digital,why:'Revisa cuáles sigues usando. No se asume que sean innecesarias.'});
  if(outside>0)candidates.push({kind:'Patrón',label:'Comida fuera de casa',amount:outside,why:'Dato para revisar si quieres ajustar frecuencia o monto.'});
  repeats.slice(0,4).forEach(x=>candidates.push({kind:'Repetido',label:x.note,amount:x.total,why:`Apareció ${x.count} veces en 30 días.`}));
  duplicates.slice(0,3).forEach(x=>candidates.push({kind:'Posible duplicado',label:x.note,amount:x.possibleExtra,why:`Mismo día y mismo monto (${x.count} registros). Verifica antes de corregir.`}));
  const reviews=await all('leakReviews'); const reviewMap=Object.fromEntries(reviews.map(r=>[r.id,r]));
  const enriched=candidates.map(x=>{const id=leakReviewId(x.kind,x.label),review=reviewMap[id]||null;return {...x,id,status:review?.status||'unreviewed',reviewedAt:review?.updatedAt||null}});
  const activeCandidates=enriched.filter(x=>x.status!=='necessary');
  const learnedNecessary=enriched.filter(x=>x.status==='necessary');
  const learnedCorrectable=enriched.filter(x=>x.status==='correctable');
  const learnedLater=enriched.filter(x=>x.status==='later');
  const potentialMonthly=[digital,...duplicates.map(x=>x.possibleExtra)].reduce((a,b)=>a+b,0); const potentialAnnual=potentialMonthly*12;
  const confirmedMonthly=learnedCorrectable.reduce((a,x)=>a+num(x.amount),0); const confirmedAnnual=confirmedMonthly*12;
  return `<section class="card hero"><div class="eyebrow">Parte 4 · Presupuesto</div><h2>Decide antes de gastar.</h2><p class="muted">Presupuesto real + análisis de patrones. Todo se calcula en tu dispositivo.</p><div class="grid two compact-stats"><div class="stat"><div class="muted small">Presupuesto del mes</div><strong>${fmt(totalLimit,s.currency)}</strong></div><div class="stat"><div class="muted small">Gastado</div><strong>${fmt(totalSpent,s.currency)}</strong></div></div></section>
  ${!diag?`<section class="card"><div class="insight">Completa primero tu diagnóstico para partir de tu disponible real. <button class="link-btn" data-route="diagnosis">Ir al diagnóstico</button></div></section>`:''}
  <section class="card"><div class="row between"><div><div class="eyebrow">${esc(currentMonth)}</div><h3>Mis límites</h3></div><span class="pill ${remaining<0?'negative':''}">${remaining>=0?'Queda ':'Exceso '}${fmt(Math.abs(remaining),s.currency)}</span></div><form id="budgetForm"><div class="stack">${rows.map(r=>`<div class="budget-row"><div class="row between"><strong>${esc(r.c)}</strong><span class="small muted">Usado ${fmt(r.used,s.currency)}</span></div><div class="grid two"><div><label>Límite mensual</label><input name="limit_${esc(r.c)}" inputmode="decimal" min="0" step="0.01" value="${Number(r.lim||0).toFixed(2)}"></div><div><label>Disponible</label><div class="budget-readout ${r.left<0?'negative':''}">${fmt(r.left,s.currency)}</div></div></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,Math.max(0,r.ratio*100))}%"></div></div><div class="tiny muted">${r.lim>0?Math.round(r.ratio*100)+'% del límite':'Sin límite definido'}</div></div>`).join('')}</div><button class="btn" type="submit">Guardar presupuesto</button></form></section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Alertas útiles</div><h3>Antes de pasarte</h3></div><span class="pill">${alerts.length}</span></div>${alerts.length?`<div class="stack">${alerts.map(r=>`<div class="history-row"><div><strong>${esc(r.c)}</strong><div class="small muted">${r.ratio>=1?'Superó el límite':'Ya consumió al menos 80% del límite'}</div></div><div class="right"><strong class="${r.ratio>=1?'negative':''}">${Math.round(r.ratio*100)}%</strong><div class="small muted">${fmt(r.used,s.currency)} / ${fmt(r.lim,s.currency)}</div></div></div>`).join('')}</div>`:'<p class="muted">Ninguna categoría ha llegado al 80% de su límite.</p>'}</section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Comparación mensual</div><h3>Qué cambió</h3></div><span class="pill">vs. ${esc(prevMonth)}</span></div>${prevItems.length?`${increases.length?`<div class="stack">${increases.slice(0,6).map(x=>`<div class="history-row"><div><strong>${esc(x.c)}</strong><div class="small muted">Antes ${fmt(x.prev,s.currency)} · ahora ${fmt(x.cur,s.currency)}</div></div><div class="right"><strong>+${Math.round(x.p*100)}%</strong><div class="small muted">+${fmt(x.delta,s.currency)}</div></div></div>`).join('')}</div>`:'<p class="muted">No detecto aumentos de 20% o más en categorías con historial comparable.</p>'}`:'<p class="muted">Necesito movimientos del mes anterior para hacer una comparación útil.</p>'}</section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Gastos pequeños</div><h3>Lo pequeño también suma</h3></div><span class="pill">${micros.length} movimientos</span></div><div class="grid two"><div class="stat"><div class="muted small">Acumulado 30 días</div><div class="value">${fmt(microTotal,s.currency)}</div></div><div class="stat"><div class="muted small">Umbral usado</div><div class="value">≤ ${fmt(microThreshold,s.currency)}</div></div></div><p class="muted small">Es una señal descriptiva: un gasto pequeño puede ser necesario. La app solo muestra su efecto acumulado.</p></section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Posibles duplicados</div><h3>Verifica antes de corregir</h3></div><span class="pill">${duplicates.length}</span></div>${duplicates.length?`<div class="stack">${duplicates.slice(0,5).map(x=>`<div class="history-row"><div><strong>${esc(x.note)}</strong><div class="small muted">${esc(x.date)} · ${x.count} registros iguales</div></div><div class="right"><strong>${fmt(x.amount,s.currency)}</strong><div class="small muted">posible extra ${fmt(x.possibleExtra,s.currency)}</div></div></div>`).join('')}</div>`:'<p class="muted">No encontré movimientos con mismo día, descripción y monto.</p>'}</section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Detector de fugas · aprende contigo</div><h3>Oportunidades para revisar</h3></div><span class="pill">${activeCandidates.length} activas</span></div>${activeCandidates.length?`<div class="stack">${activeCandidates.slice(0,8).map(x=>`<div class="history-row leak-row"><div class="grow"><div class="row wrap"><span class="pill">${esc(x.kind)}</span>${x.status!=='unreviewed'?`<span class="pill status-${esc(x.status)}">${leakStatusLabel(x.status)}</span>`:''}</div><strong>${esc(x.label)}</strong><div class="small muted">${esc(x.why)}</div><div class="leak-actions"><button class="btn ghost mini" data-action="review-leak" data-id="${esc(x.id)}" data-kind="${esc(x.kind)}" data-label="${esc(x.label)}" data-status="necessary">Necesario</button><button class="btn ghost mini" data-action="review-leak" data-id="${esc(x.id)}" data-kind="${esc(x.kind)}" data-label="${esc(x.label)}" data-status="later">Revisar después</button><button class="btn secondary mini" data-action="review-leak" data-id="${esc(x.id)}" data-kind="${esc(x.kind)}" data-label="${esc(x.label)}" data-status="correctable">Corregible</button></div></div><div class="right"><strong>${fmt(x.amount,s.currency)}</strong></div></div>`).join('')}</div>`:'<p class="muted">No tienes oportunidades pendientes. Las que marcaste como necesarias dejan de aparecer como alertas activas.</p>'}<div class="insight"><strong>Escenario máximo a revisar:</strong> ${fmt(potentialMonthly,s.currency)}/mes · ${fmt(potentialAnnual,s.currency)}/año. <span class="small">No es ahorro garantizado.</span></div>${confirmedMonthly>0?`<div class="insight success-insight"><strong>Oportunidad que tú confirmaste como corregible:</strong> ${fmt(confirmedMonthly,s.currency)}/mes · ${fmt(confirmedAnnual,s.currency)}/año.</div>`:''}</section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Tus decisiones</div><h3>Lo que la app ya aprendió</h3></div><span class="pill">${learnedNecessary.length+learnedLater.length+learnedCorrectable.length}</span></div><div class="grid three"><div class="stat"><div class="muted small">Necesarios</div><div class="value">${learnedNecessary.length}</div></div><div class="stat"><div class="muted small">Revisar después</div><div class="value">${learnedLater.length}</div></div><div class="stat"><div class="muted small">Corregibles</div><div class="value">${learnedCorrectable.length}</div></div></div>${learnedNecessary.length?`<details class="details-box"><summary>Ver gastos que decidí no tratar como fuga</summary><div class="stack">${learnedNecessary.map(x=>`<div class="row between small"><span>${esc(x.label)}</span><button class="link-btn" data-action="review-leak" data-id="${esc(x.id)}" data-kind="${esc(x.kind)}" data-label="${esc(x.label)}" data-status="later">Cambiar decisión</button></div>`).join('')}</div></details>`:''}<p class="muted small">Estas decisiones se guardan en el dispositivo y también entran en tu respaldo. Así el detector deja de insistir con gastos que tú ya consideraste necesarios.</p></section>`
}


async function reserveView(){
  const s=await settings();
  const reserve=await get('reserves','emergency')||{id:'emergency',monthlyEssential:0,targetMonths:3,currentAmount:0,monthlyContributionTarget:0};
  const monthly=num(reserve.monthlyEssential), targetMonths=Math.max(1,Number(reserve.targetMonths||3)), current=num(reserve.currentAmount), target=monthly*targetMonths;
  const reserveMonthly=num(reserve.monthlyContributionTarget), progress=target>0?Math.min(100,(current/target)*100):0, monthsCovered=monthly>0?current/monthly:0, missing=Math.max(0,target-current);
  const goals=(await all('goals')).filter(g=>!g.deletedAt).sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt));
  const planned=(await all('plannedExpenses')).filter(x=>!x.deletedAt).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));
  const contributions=(await all('contributions')).filter(x=>!x.deletedAt).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
  const annualTotal=planned.reduce((a,x)=>a+num(x.annualAmount),0), annualMonthly=annualTotal/12;
  const diag=await get('diagnosis',DIAGNOSIS_ID), available=num(diag?.calculated?.available);
  const budget=await get('budgets',monthKey(localDateISO()));
  // El plan de ahorro no debe restar dos veces la categoría Ahorro / metas.
  // Para calcular capacidad, usamos solo el presupuesto de vida/operación y luego asignamos reserva, previsibles y metas.
  const budgetLivingTotal=budget?Object.entries(budget.limits||{}).filter(([k])=>k!=='Ahorro / metas').reduce((a,[,v])=>a+num(v),0):0;
  const savingsBudgetLimit=budget?num((budget.limits||{})['Ahorro / metas']):0;
  const capacity=diag&&budget?Math.max(0,available-budgetLivingTotal):0;
  const goalNeeds=goals.map(g=>{const remaining=Math.max(0,num(g.targetAmount)-num(g.currentAmount));let monthlyNeed=0;if(g.targetDate&&remaining>0){const now=new Date(),end=new Date(`${g.targetDate}T12:00:00`);const months=Math.max(1,Math.ceil((end-now)/(1000*60*60*24*30.4375)));monthlyNeed=remaining/months;}return {id:g.id,name:g.name,monthlyNeed,remaining}});
  const goalMonthly=goalNeeds.reduce((a,g)=>a+g.monthlyNeed,0), requested=reserveMonthly+annualMonthly+goalMonthly;
  let left=capacity;
  const planReserve=Math.min(reserveMonthly,left);left-=planReserve;
  const planPredictable=Math.min(annualMonthly,left);left-=planPredictable;
  const planGoals=Math.min(goalMonthly,left);left-=planGoals;
  const shortfall=Math.max(0,requested-capacity);
  return `<section class="card hero"><div class="eyebrow">Parte 5 · Reserva y metas</div><h2>Tu tranquilidad primero</h2><p class="muted">Reserva, metas y gastos previsibles conectados con tu capacidad mensual real, sin doble conteo.</p></section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Fondo de emergencia</div><h3>Reserva personal</h3></div><span class="pill">${monthsCovered.toFixed(1)} meses cubiertos</span></div>
    <div class="grid two"><div class="stat"><div class="muted small">Reserva actual</div><div class="value">${fmt(current,s.currency)}</div></div><div class="stat"><div class="muted small">Meta de reserva</div><div class="value">${fmt(target,s.currency)}</div></div></div>
    <div class="progress-line"><div class="progress-track"><div class="progress-fill" style="width:${progress}%"></div></div><div class="row between tiny muted"><span>${Math.round(progress)}% completado</span><span>${missing>0?`Faltan ${fmt(missing,s.currency)}`:'Meta alcanzada'}</span></div></div>
    <form id="reserveForm"><label>Gasto esencial mensual</label><input name="monthlyEssential" inputmode="decimal" min="0" step="0.01" value="${Number(monthly).toFixed(2)}" required><label>Meses que quieres cubrir</label><select name="targetMonths">${[1,2,3,4,5,6,9,12].map(m=>`<option value="${m}" ${m===targetMonths?'selected':''}>${m} mes${m===1?'':'es'}</option>`).join('')}</select><label>Reserva actual</label><input name="currentAmount" inputmode="decimal" min="0" step="0.01" value="${Number(current).toFixed(2)}" required><label>Aporte mensual que quieres intentar</label><input name="monthlyContributionTarget" inputmode="decimal" min="0" step="0.01" value="${Number(reserveMonthly).toFixed(2)}"><button class="btn" type="submit">Guardar reserva</button></form>
    <button class="btn secondary" data-action="add-reserve">Añadir aporte a reserva</button><p class="muted small">Cada aporte queda en un historial y se registra como movimiento de “Ahorro / metas”.</p>
  </section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Gastos previsibles</div><h3>Lo que sabes que llegará</h3></div><span class="pill">${fmt(annualMonthly,s.currency)}/mes</span></div>
    <form id="plannedExpenseForm"><label>Nombre</label><input name="name" maxlength="60" placeholder="Seguro, mantenimiento, matrícula..." required><div class="grid two"><div><label>Monto anual</label><input name="annualAmount" inputmode="decimal" min="0.01" step="0.01" required></div><div><label>Fecha estimada (opcional)</label><input name="dueDate" type="date"></div></div><button class="btn secondary" type="submit">Añadir gasto previsible</button></form>
    <div class="stack">${planned.length?planned.map(x=>`<div class="history-row"><div class="grow"><strong>${esc(x.name)}</strong><div class="small muted">${fmt(x.annualAmount,s.currency)} al año · separar ${fmt(num(x.annualAmount)/12,s.currency)}/mes${x.dueDate?` · ${esc(x.dueDate)}`:''}</div></div><button class="btn ghost mini" data-action="delete-planned" data-id="${esc(x.id)}">Eliminar</button></div>`).join(''):'<p class="muted">Todavía no registraste gastos previsibles del año.</p>'}</div>
  </section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Plan mensual</div><h3>Cuánto separar sin inventar dinero</h3></div><span class="pill">${fmt(requested,s.currency)} solicitado</span></div>
    ${!diag?'<div class="insight">Completa el diagnóstico para calcular tu capacidad real.</div>':!budget?'<div class="insight">Define primero el presupuesto mensual. Sin ese dato no voy a fingir una capacidad de ahorro.</div>':`<div class="grid two"><div class="stat"><div class="muted small">Disponible real</div><div class="value">${fmt(available,s.currency)}</div></div><div class="stat"><div class="muted small">Capacidad después del presupuesto de vida</div><div class="value">${fmt(capacity,s.currency)}</div></div></div><div class="stack"><div class="history-row"><div><strong>1. Reserva</strong><div class="small muted">Prioridad de protección</div></div><strong>${fmt(planReserve,s.currency)}</strong></div><div class="history-row"><div><strong>2. Gastos previsibles</strong><div class="small muted">Cuota anual dividida entre 12</div></div><strong>${fmt(planPredictable,s.currency)}</strong></div><div class="history-row"><div><strong>3. Metas con fecha</strong><div class="small muted">Se asigna lo que quede</div></div><strong>${fmt(planGoals,s.currency)}</strong></div></div><div class="muted small">La categoría “Ahorro / metas” (${fmt(savingsBudgetLimit,s.currency)}) no se descuenta aquí para evitar contar el ahorro dos veces.</div>${shortfall>0?`<div class="insight"><strong>No alcanza para todo este mes.</strong> Faltan ${fmt(shortfall,s.currency)}. La app prioriza reserva, luego previsibles y después metas; no aumenta tu capacidad artificialmente.</div>`:'<div class="insight success-insight"><strong>El plan cabe dentro de tu capacidad actual.</strong> Quedarían ${fmt(left,s.currency)} sin asignar.</div>'}`}
  </section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Objetivos</div><h3>Mis metas</h3></div><span class="pill">${goals.length}</span></div>
    <form id="goalForm"><label>Nombre de la meta</label><input name="name" maxlength="60" placeholder="Ej. Viaje, computadora, inicial..." required><div class="grid two"><div><label>Monto objetivo</label><input name="targetAmount" inputmode="decimal" min="0.01" step="0.01" required></div><div><label>Ya tengo</label><input name="currentAmount" inputmode="decimal" min="0" step="0.01" value="0"></div></div><label>Fecha objetivo (opcional)</label><input name="targetDate" type="date"><button class="btn secondary" type="submit">Crear meta</button></form>
    <div class="stack">${goals.length?goals.map(g=>{const target=num(g.targetAmount),cur=num(g.currentAmount),p=target>0?Math.min(100,cur/target*100):0,remaining=Math.max(0,target-cur);let monthlyNeeded='';if(g.targetDate){const now=new Date();const end=new Date(`${g.targetDate}T12:00:00`);const months=Math.max(1,Math.ceil((end-now)/(1000*60*60*24*30.4375)));monthlyNeeded=` · ${fmt(remaining/months,s.currency)}/mes`;}return `<div class="history-row"><div class="grow"><strong>${esc(g.name)}</strong><div class="small muted">${fmt(cur,s.currency)} de ${fmt(target,s.currency)}${g.targetDate?` · Meta ${esc(g.targetDate)}`:''}</div><div class="progress-track"><div class="progress-fill" style="width:${p}%"></div></div><div class="tiny muted">${Math.round(p)}% · faltan ${fmt(remaining,s.currency)}${monthlyNeeded}</div><div class="row wrap"><button class="btn ghost mini" data-action="add-goal" data-id="${esc(g.id)}">Añadir aporte</button><button class="btn ghost mini" data-action="edit-goal" data-id="${esc(g.id)}">Editar</button><button class="btn ghost mini" data-action="delete-goal" data-id="${esc(g.id)}">Eliminar</button></div></div></div>`}).join(''):'<p class="muted">Todavía no tienes metas.</p>'}</div>
  </section>
  <section class="card"><div class="row between"><div><div class="eyebrow">Historial</div><h3>Aportes realizados</h3></div><span class="pill">${contributions.length}</span></div>${contributions.length?`<div class="stack">${contributions.slice(0,20).map(c=>`<div class="history-row"><div class="grow"><strong>${esc(c.destinationName||c.destinationType)}</strong><div class="small muted">${esc(c.date||'')} · ${esc(c.note||'Aporte')}</div></div><strong>${fmt(c.amount,s.currency)}</strong><button class="btn ghost mini" data-action="undo-contribution" data-id="${esc(c.id)}">Deshacer</button></div>`).join('')}</div>`:'<p class="muted">Aún no hay aportes registrados.</p>'}</section>`
}


function debtMonths(balance,annualRate,payment){
  balance=num(balance);payment=num(payment);const r=num(annualRate)/1200;
  if(balance<=0)return 0;if(payment<=0)return Infinity;
  if(r===0)return Math.ceil(balance/payment);
  if(payment<=balance*r)return Infinity;
  return Math.ceil(-Math.log(1-r*balance/payment)/Math.log(1+r));
}
function debtMethod(debts){return debts.length>4?'snowball':'avalanche'}
function debtOrder(debts,method){return [...debts].sort((a,b)=>method==='snowball'?num(a.balance)-num(b.balance):num(b.annualRate)-num(a.annualRate))}
function addMonthsISO(months){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+Number(months||0));return d.toISOString().slice(0,10)}
function monthsUntil(date){if(!date)return null;const now=new Date(),end=new Date(`${date}T12:00:00`);if(end<=now)return 0;return Math.max(1,Math.ceil((end-now)/(1000*60*60*24*30.4375)))}
function simulateDebtPlan(debts,method,extraMonthly=0){
  const active=debts.filter(d=>!d.deletedAt&&num(d.balance)>0).map(d=>({id:d.id,name:d.name,balance:num(d.balance),annualRate:num(d.annualRate),minPayment:num(d.minPayment)}));
  if(!active.length)return {months:0,totalInterest:0,totalPaid:0,monthlyBudget:0,timeline:[],finished:true};
  const originalTotal=active.reduce((a,d)=>a+d.balance,0),monthlyBudget=active.reduce((a,d)=>a+d.minPayment,0)+num(extraMonthly);
  if(monthlyBudget<=0)return {months:Infinity,totalInterest:0,totalPaid:0,monthlyBudget,timeline:[],finished:false};
  let months=0,totalInterest=0,totalPaid=0;const timeline=[];
  while(active.some(d=>d.balance>0.005)&&months<600){
    months++;
    for(const d of active){if(d.balance<=0.005)continue;const interest=d.balance*(d.annualRate/1200);d.balance+=interest;totalInterest+=interest;}
    let budget=monthlyBudget;
    for(const d of active){if(d.balance<=0.005||budget<=0)continue;const pay=Math.min(d.minPayment,d.balance,budget);d.balance-=pay;budget-=pay;totalPaid+=pay;if(d.balance<=0.005){d.balance=0;timeline.push({id:d.id,name:d.name,month:months})}}
    let guard=0;
    while(budget>0.005&&active.some(d=>d.balance>0.005)&&guard++<active.length+3){const target=debtOrder(active.filter(d=>d.balance>0.005),method)[0];if(!target)break;const pay=Math.min(target.balance,budget);target.balance-=pay;budget-=pay;totalPaid+=pay;if(target.balance<=0.005){target.balance=0;timeline.push({id:target.id,name:target.name,month:months})}}
    if(months>=24&&timeline.length===0&&active.reduce((a,d)=>a+d.balance,0)>originalTotal*1.1)break;
  }
  const finished=!active.some(d=>d.balance>0.005);return {months:finished?months:Infinity,totalInterest,totalPaid,monthlyBudget,timeline,finished};
}
async function undoDebtPaymentById(paymentId,{ask=true}={}){
  const pay=await get('debtPayments',paymentId);if(!pay||pay.deletedAt)return false;
  if(ask&&!confirm(`¿Deshacer el pago de ${fmt(pay.amount,(await settings()).currency)} a “${pay.debtName}”?`))return false;
  const d=await get('debts',pay.debtId),now=new Date().toISOString();
  if(d){d.balance=num(d.balance)+num(pay.amount);d.paidAt=null;d.updatedAt=now;await put('debts',d)}
  pay.deletedAt=now;pay.updatedAt=now;await put('debtPayments',pay);
  if(pay.transactionId){const tx=await get('transactions',pay.transactionId);if(tx&&!tx.deletedAt){tx.deletedAt=now;tx.updatedAt=now;await put('transactions',tx);await enqueue('transaction.deleted',{id:tx.id,updatedAt:now})}}
  await put('audit',{id:newId('audit'),type:'debt.payment.undone',at:now,debtId:pay.debtId,debtPaymentId:pay.id,amount:pay.amount});return true;
}

