async function onChange(e){
  if(e.target.id==='makeRecurring'){document.querySelector('#recurringOptions')?.classList.toggle('hidden',!e.target.checked);return}
  if(e.target.name==='type' && e.target.closest('#transactionForm')){const sel=document.querySelector('#transactionCategory');if(sel){const list=e.target.value==='income'?incomeCategories:expenseCategories;sel.innerHTML=list.map(c=>`<option>${c}</option>`).join('')}return}
  if(e.target.id==='incomeType'){document.querySelector('#fixedIncomeBox')?.classList.toggle('hidden',e.target.value==='variable');document.querySelector('#variableIncomeBox')?.classList.toggle('hidden',e.target.value!=='variable');return}
  if(e.target.id!=='restoreFile')return;const file=e.target.files?.[0];if(!file)return;try{const password=prompt('Contraseña del respaldo:');if(password===null)return;const data=await decryptBackup(await file.text(),password);if(!confirm('Restaurar reemplazará los datos actuales. ¿Continuar?'))return;await createLocalSnapshot('antes de restaurar respaldo externo');await importAll(data);unlocked=false;route='home';await render();await updateStatus();showToast('Respaldo restaurado')}catch(err){showToast(err.message||'No se pudo restaurar')}
}
